/**
 * BEAN Intelligence — giftz-kit implementation validation, scaled to the
 * expanded internal library (Phase 1 rule: "never advertise a component as
 * installed unless its implementation exists and HAS PASSED validation").
 *
 * Three layers:
 *  1. COVERAGE: every kit .tsx is recorded in the SSR manifest
 *     (tests/unit/giftz-kit-ssr-manifest.json, generated by
 *     scripts/kit-ssr-probe.tsx) — nothing ships unclassified.
 *  2. SYNTAX: every kit .tsx/.css parses (Bun transpiler scan — a real
 *     parse, not a heuristic) + stylesheets are balanced and non-empty.
 *  3. SSR SMOKE: every manifest entry marked ssr:true renders through
 *     react-dom/server (with the recorded props for needs-props entries);
 *     the ONE browser-only entry (WarmTooltip) is validated by layers 1-2
 *     plus the repo tsc gate — it is honestly recorded, never advertised
 *     as SSR-capable, and works in generated React projects (client-side).
 */
import { describe, test, expect } from 'bun:test'
import { readFileSync, readdirSync, existsSync } from 'fs'
import path from 'path'
import { createElement, type FC as ReactFC } from 'react'
import { renderToString } from 'react-dom/server'

const KIT_DIR = path.join(import.meta.dir, '../../src/components/giftz-kit')
const MANIFEST_PATH = path.join(import.meta.dir, 'giftz-kit-ssr-manifest.json')

interface Manifest {
  generatedBy: string
  components: Record<string, { ssr: boolean; props: Record<string, unknown> }>
}

const manifest: Manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8'))

/** The original integration's named SSR cases (kept from the first task). */
const ORIGINAL_SSR_CASES: Array<[string, Record<string, unknown>]> = [
  ['ShinyText', {}],
  ['GradientText', {}],
  ['StarBorder', {}],
  ['SpotlightCard', {}],
  ['GlareHover', {}],
  ['GlassSurface', {}],
  ['LetterGlitch', {}],
  ['DotGrid', {}],
  ['LatticeLoader', {}],
  ['ClickSpark', {}],
  ['BlurText', { text: 'Hello BEAN' }],
  ['CountUp', { to: 100 }],
  ['SplitText', { text: 'Hello BEAN' }],
  ['ScrollReveal', { children: 'Hi' }],
  ['AnimatedContent', { children: 'Hi' }],
]

describe('giftz-kit implementation validation (expanded kit)', () => {
  const tsxFiles = readdirSync(KIT_DIR).filter((f) => f.endsWith('.tsx'))

  test('the kit contains the full expanded installed set (168 components) and the manifest covers every file', () => {
    expect(tsxFiles.length).toBe(168)
    const names = tsxFiles.map((f) => f.replace(/\.tsx$/, ''))
    for (const name of names) {
      expect(manifest.components[name], `${name} missing from the SSR manifest`).toBeTruthy()
    }
    expect(Object.keys(manifest.components).length).toBe(168)
  })

  test('every kit component parses (Bun transpiler — real syntax gate)', () => {
    const transpiler = new Bun.Transpiler({ loader: 'tsx' })
    for (const file of tsxFiles) {
      const src = readFileSync(path.join(KIT_DIR, file), 'utf8')
      expect(() => transpiler.scanImports(src), `${file} has broken syntax`).not.toThrow()
    }
  })

  test('every kit stylesheet parses (balanced braces, non-empty)', () => {
    for (const file of readdirSync(KIT_DIR).filter((f) => f.endsWith('.css'))) {
      const src = readFileSync(path.join(KIT_DIR, file), 'utf8')
      expect(src.trim().length).toBeGreaterThan(0)
      expect((src.match(/{/g) ?? []).length, `${file} unbalanced braces`).toBe((src.match(/}/g) ?? []).length)
    }
  })

  test('every component recorded ssr:true renders server-side without throwing (with its recorded props)', async () => {
    const ssrNames = Object.entries(manifest.components)
      .filter(([, v]) => v.ssr)
      .map(([k]) => k)
      .sort()
    // 167 of 168 render on the server (only WarmTooltip needs the browser).
    expect(ssrNames.length).toBe(167)
    for (const name of ssrNames) {
      const entry = manifest.components[name]!
      const mod = (await import(path.join(KIT_DIR, `${name}.tsx`))) as unknown as {
        default: (props: never) => unknown
      }
      const Comp = mod.default as unknown as ReactFC<Record<string, unknown>>
      // The manifest's recorded contract: renders WITHOUT THROWING on the
      // server (some mount-only components legitimately render nothing).
      expect(() => renderToString(createElement(Comp, entry.props)), `${name} threw on SSR`).not.toThrow()
    }
  })

  test('the one browser-only component is honestly recorded and never silently advertised', () => {
    const browserOnly = Object.entries(manifest.components)
      .filter(([, v]) => !v.ssr)
      .map(([k]) => k)
    expect(browserOnly).toEqual(['WarmTooltip'])
    expect(existsSync(path.join(KIT_DIR, 'WarmTooltip.tsx'))).toBe(true)
  })

  test('the original 15 named SSR cases still render non-empty markup (regression guard)', async () => {
    type KitLoader = () => Promise<{ default: (props: never) => unknown }>
    const KIT_MODULES: Record<string, KitLoader> = {
      ShinyText: () => import('../../src/components/giftz-kit/ShinyText'),
      GradientText: () => import('../../src/components/giftz-kit/GradientText'),
      StarBorder: () => import('../../src/components/giftz-kit/StarBorder'),
      SpotlightCard: () => import('../../src/components/giftz-kit/SpotlightCard'),
      GlareHover: () => import('../../src/components/giftz-kit/GlareHover'),
      GlassSurface: () => import('../../src/components/giftz-kit/GlassSurface'),
      LetterGlitch: () => import('../../src/components/giftz-kit/LetterGlitch'),
      DotGrid: () => import('../../src/components/giftz-kit/DotGrid'),
      LatticeLoader: () => import('../../src/components/giftz-kit/LatticeLoader'),
      ClickSpark: () => import('../../src/components/giftz-kit/ClickSpark'),
      BlurText: () => import('../../src/components/giftz-kit/BlurText'),
      CountUp: () => import('../../src/components/giftz-kit/CountUp'),
      SplitText: () => import('../../src/components/giftz-kit/SplitText'),
      ScrollReveal: () => import('../../src/components/giftz-kit/ScrollReveal'),
      AnimatedContent: () => import('../../src/components/giftz-kit/AnimatedContent'),
    }
    for (const [name, props] of ORIGINAL_SSR_CASES) {
      const loader = KIT_MODULES[name]
      expect(loader, `${name} missing from the SSR module map`).toBeTruthy()
      const { default: Comp } = await loader()
      // useGSAP/@gsap/react is isomorphic: it must NOT throw on the server.
      const html = renderToString(createElement(Comp as unknown as ReactFC<Record<string, unknown>>, props)) as string
      expect(html.length, `${name} rendered empty`).toBeGreaterThan(10)
    }
  })

  test('the adapted framer-motion components render real text (motion/react replacement verified)', async () => {
    const { default: BlurText } = (await import('../../src/components/giftz-kit/BlurText')) as {
      default: (p: { text: string }) => unknown
    }
    const html = renderToString(createElement(BlurText as unknown as ReactFC<{ text: string }>, { text: 'Attribution preserved' })) as string
    expect(html).toContain('Attribution')
  })
})
